-- Bookings. booking_status (trip lifecycle) and payment_status (money
-- summary) are separate state machines; transitions are enforced by triggers
-- in a later migration. payments/payment_orders are the source of truth for
-- money; bookings.payment_status is a summary kept in sync by server code.

create table public.bookings (
  id                    uuid primary key default gen_random_uuid(),
  -- Non-sequential, unambiguous alphabet (no 0/O/1/I). Generated by the app.
  booking_reference     text not null unique
                          check (booking_reference ~ '^PT-[23456789ABCDEFGHJKLMNPQRSTUVWXYZ]{8}$'),
  customer_id           uuid not null references public.customers (id) on delete restrict,

  booking_kind          text not null check (booking_kind in ('cab', 'package')),
  trip_type             text not null check (
                          trip_type in ('one_way', 'round_trip', 'local', 'airport_transfer', 'railway_transfer', 'package')
                        ),
  route_id              uuid references public.routes (id) on delete restrict,
  route_fare_id         uuid references public.route_fares (id) on delete restrict,
  vehicle_category_id   uuid references public.vehicle_categories (id) on delete restrict,
  package_id            uuid references public.tour_packages (id) on delete restrict,

  pickup_location       text not null check (char_length(pickup_location) between 3 and 300),
  destination           text check (char_length(destination) <= 300),
  pickup_at             timestamptz not null,
  return_at             timestamptz,
  passenger_count       smallint not null check (passenger_count between 1 and 60),
  special_instructions  text check (char_length(special_instructions) <= 1000),

  -- Immutable pricing snapshot computed server-side at booking time.
  fare_snapshot         jsonb not null check (jsonb_typeof(fare_snapshot) = 'object'),
  total_amount_paise    bigint not null check (total_amount_paise > 0),
  currency              text not null default 'INR' check (currency = 'INR'),

  booking_status        text not null default 'pending_payment' check (
                          booking_status in ('pending_payment', 'confirmed', 'assigned', 'in_progress', 'completed', 'cancelled')
                        ),
  payment_status        text not null default 'unpaid' check (
                          payment_status in ('unpaid', 'paid', 'refund_pending', 'partially_refunded', 'refunded')
                        ),

  terms_version         text not null check (char_length(terms_version) between 1 and 40),
  terms_accepted_at     timestamptz not null,
  payment_expires_at    timestamptz,

  -- Set when money and trip state disagree (e.g. payment captured after the
  -- booking was cancelled). Such bookings must be resolved by an admin and
  -- are never auto-assigned.
  needs_reconciliation  boolean not null default false,
  reconciliation_note   text check (char_length(reconciliation_note) <= 1000),

  cancellation_reason   text check (
                          cancellation_reason in ('customer_request', 'payment_expired', 'admin', 'no_vehicle', 'other')
                        ),
  cancelled_at          timestamptz,

  created_at            timestamptz not null default now(),
  updated_at            timestamptz not null default now(),

  constraint bookings_return_after_pickup check (return_at is null or return_at > pickup_at),
  constraint bookings_round_trip_needs_return check (trip_type <> 'round_trip' or return_at is not null),
  constraint bookings_kind_matches_trip check ((booking_kind = 'package') = (trip_type = 'package')),
  constraint bookings_cab_refs check (
    booking_kind <> 'cab'
    or (route_id is not null and route_fare_id is not null and vehicle_category_id is not null)
  ),
  constraint bookings_package_refs check (booking_kind <> 'package' or package_id is not null),
  constraint bookings_cancel_fields check (
    (booking_status = 'cancelled') = (cancelled_at is not null and cancellation_reason is not null)
  )
);

create index bookings_customer_idx on public.bookings (customer_id);
create index bookings_status_pickup_idx on public.bookings (booking_status, pickup_at);
create index bookings_payment_status_idx on public.bookings (payment_status);
create index bookings_created_at_idx on public.bookings (created_at desc);
create index bookings_pickup_at_idx on public.bookings (pickup_at);
create index bookings_pending_expiry_idx on public.bookings (payment_expires_at)
  where booking_status = 'pending_payment';
create index bookings_reconciliation_idx on public.bookings (created_at)
  where needs_reconciliation;

create trigger bookings_set_updated_at
  before update on public.bookings
  for each row execute function public.set_updated_at();

-- Enquiries: for routes/categories without an approved fare, unpriced tour
-- packages, and hotel / flight / train booking assistance.
create table public.enquiries (
  id                   uuid primary key default gen_random_uuid(),
  customer_id          uuid not null references public.customers (id) on delete restrict,
  enquiry_type         text not null check (
                         enquiry_type in ('cab', 'package', 'hotel', 'flight_train', 'general')
                       ),
  route_id             uuid references public.routes (id) on delete set null,
  vehicle_category_id  uuid references public.vehicle_categories (id) on delete set null,
  package_id           uuid references public.tour_packages (id) on delete set null,
  pickup_location      text check (char_length(pickup_location) <= 300),
  destination          text check (char_length(destination) <= 300),
  travel_date          date,
  passenger_count      smallint check (passenger_count between 1 and 60),
  message              text check (char_length(message) <= 2000),
  status               text not null default 'new' check (status in ('new', 'contacted', 'converted', 'closed')),
  created_at           timestamptz not null default now(),
  updated_at           timestamptz not null default now()
);

create index enquiries_status_created_idx on public.enquiries (status, created_at desc);
create index enquiries_customer_idx on public.enquiries (customer_id);

create trigger enquiries_set_updated_at
  before update on public.enquiries
  for each row execute function public.set_updated_at();
